import{_ as o,o as a,c as i,a2 as s}from"./chunks/framework.CqpfiAoK.js";const p=JSON.parse('{"title":"Mecanismo de Abertura de Recursos de Cultivo","description":"","frontmatter":{},"headers":[],"relativePath":"pt/18-修炼资源开放机制.md","filePath":"pt/18-修炼资源开放机制.md","lastUpdated":null}'),r={name:"pt/18-修炼资源开放机制.md"};function t(d,e,c,n,u,l){return a(),i("div",null,[...e[0]||(e[0]=[s('<h1 id="mecanismo-de-abertura-de-recursos-de-cultivo" tabindex="-1">Mecanismo de Abertura de Recursos de Cultivo <a class="header-anchor" href="#mecanismo-de-abertura-de-recursos-de-cultivo" aria-label="Permalink to &quot;Mecanismo de Abertura de Recursos de Cultivo&quot;">​</a></h1><table tabindex="0"><thead><tr><th>Projeto</th><th>Conteúdo</th></tr></thead><tbody><tr><td>Número do Documento</td><td>18</td></tr><tr><td>Módulo</td><td>Leis Cósmicas e Sistemas de Cultivo</td></tr><tr><td>Palavras-chave</td><td>Abertura de Recursos, Recursos de Cultivo, Mecanismo de Distribuição, Antimonopólio, Equidade de Recursos</td></tr></tbody></table><h2 id="i-contexto-e-significado-do-mecanismo-de-abertura-de-recursos-de-cultivo" tabindex="-1">I. Contexto e Significado do Mecanismo de Abertura de Recursos de Cultivo <a class="header-anchor" href="#i-contexto-e-significado-do-mecanismo-de-abertura-de-recursos-de-cultivo" aria-label="Permalink to &quot;I. Contexto e Significado do Mecanismo de Abertura de Recursos de Cultivo&quot;">​</a></h2><p>Na era do saque, os recursos de cultivo eram o objeto de disputa mais central. Veios espirituais, campos de ervas medicinais, veios de minério de energia, tesouros celestiais, reinos secretos de cultivo e outros recursos eram monopolizados por poucos poderosos e seitas, e as massas na base quase não conseguiam obter recursos de cultivo formais. Esse monopólio de recursos não apenas causou uma grave estratificação social rígida, mas também levou a inúmeras guerras e massacres causados por disputas de recursos. O monopólio de recursos é a base econômica do sistema de saque — enquanto os recursos forem monopolizados por poucos, &quot;cada um tem um caminho&quot; só pode ser uma frase vazia.</p><p>Após o estabelecimento da Civilização Simbiótica de Âncora, a &quot;abertura de recursos de cultivo&quot; foi adotada como uma das transformações institucionais mais centrais. O objetivo central do mecanismo de abertura de recursos de cultivo é: quebrar o monopólio de recursos, garantir que cada vida possa obter recursos básicos de cultivo e, ao mesmo tempo, incentivar o uso eficiente e a criação contínua de recursos por meio do mecanismo de distribuição de &quot;mais trabalho, mais ganho&quot;. A abertura de recursos não significa &quot;distribuição igualitária de recursos&quot;, mas sim &quot;acesso equitativo a recursos&quot; — sob a premissa de garantir as necessidades básicas, a distribuição de recursos está vinculada à contribuição individual, e ao mesmo tempo qualquer forma de monopólio de recursos é estritamente proibida.</p><p>O significado do mecanismo de abertura de recursos de cultivo reside em: ele erradica o solo do saque a partir da base econômica, fornece garantia material para a verdadeira popularização dos trezentos sistemas de cultivo, fornece suporte de recursos para o objetivo social de &quot;cada um tem um caminho&quot; e cria um ponto de partida equitativo para o progresso comum de todas as raças.</p><h2 id="ii-classificacao-e-nivelamento-dos-recursos-de-cultivo" tabindex="-1">II. Classificação e Nivelamento dos Recursos de Cultivo <a class="header-anchor" href="#ii-classificacao-e-nivelamento-dos-recursos-de-cultivo" aria-label="Permalink to &quot;II. Classificação e Nivelamento dos Recursos de Cultivo&quot;">​</a></h2><h3 id="_2-1-classificacao-de-recursos" tabindex="-1">2.1 Classificação de Recursos <a class="header-anchor" href="#_2-1-classificacao-de-recursos" aria-label="Permalink to &quot;2.1 Classificação de Recursos&quot;">​</a></h3><p>Os recursos de cultivo no Heng Yuan Zhou são divididos nas seguintes categorias principais de acordo com sua natureza e uso:</p><table tabindex="0"><thead><tr><th>Categoria de Recurso</th><th>Conteúdo Específico</th><th>Uso Principal</th></tr></thead><tbody><tr><td>Recursos de Energia</td><td>Veios espirituais, veios de minério de energia, cristais de energia espiritual, fragmentos de energia original, etc.</td><td>Fornecer entrada de energia necessária para o cultivo</td></tr><tr><td>Recursos Medicinais</td><td>Ervas espirituais, plantas imortais, materiais para refinação de pílulas, pílulas prontas, etc.</td><td>Auxiliar o cultivo, tratar ferimentos, romper gargalos</td></tr><tr><td>Recursos de Equipamentos</td><td>Artefatos de cultivo, instrumentos de lei, dispositivos de duplicação, equipamentos espaciais, etc.</td><td>Melhorar a eficiência do cultivo, auxiliar o controle de leis</td></tr><tr><td>Recursos Espaciais</td><td>Reinos secretos de cultivo, zonas de concentração de energia espiritual, salas de percepção de lei, espaços isolados, etc.</td><td>Fornecer ambientes especiais de cultivo</td></tr><tr><td>Recursos de Conhecimento</td><td>Técnicas de cultivo, experiências de cultivo, materiais de pesquisa de lei, documentos técnicos, etc.</td><td>Fornecer orientação teórica e metodológica para o cultivo</td></tr><tr><td>Recursos Biológicos</td><td>Bestas espirituais, plantas espirituais, vidas contratadas, simbiontes, etc.</td><td>Fornecer auxílio ao cultivo, ciclo simbiótico, habilidades especiais</td></tr><tr><td>Recursos de Plano</td><td>Planos não desenvolvidos, direitos de uso de canais de plano, fragmentos de núcleo de plano, etc.</td><td>Fornecer espaço de cultivo e desenvolvimento em larga escala</td></tr></tbody></table><h3 id="_2-2-nivelamento-de-recursos" tabindex="-1">2.2 Nivelamento de Recursos <a class="header-anchor" href="#_2-2-nivelamento-de-recursos" aria-label="Permalink to &quot;2.2 Nivelamento de Recursos&quot;">​</a></h3><p>Todos os recursos de cultivo são divididos em cinco níveis de acordo com sua raridade e valor:</p><table tabindex="0"><thead><tr><th>Nível</th><th>Nome</th><th>Raridade</th><th>Método de Distribuição</th></tr></thead><tbody><tr><td>Nível 1</td><td>Recursos Comuns</td><td>Amplamente distribuídos, reservas abundantes</td><td>Abertura gratuita ou fornecimento a baixo preço</td></tr><tr><td>Nível 2</td><td>Recursos Excelentes</td><td>Relativamente comuns, reservas moderadas</td><td>Fornecimento básico + troca por contribuição</td></tr><tr><td>Nível 3</td><td>Recursos Raros</td><td>Relativamente raros, reservas limitadas</td><td>Troca por contribuição + aprovação de solicitação</td></tr><tr><td>Nível 4</td><td>Recursos Épicos</td><td>Muito raros, reservas escassas</td><td>Distribuição competitiva + prioridade para projetos de nível civilizacional</td></tr><tr><td>Nível 5</td><td>Recursos Lendários</td><td>Extremamente raros, quase extintos</td><td>Distribuição especial pelo órgão de decisão supremo da civilização</td></tr></tbody></table><h2 id="iii-principios-centrais-da-abertura-de-recursos" tabindex="-1">III. Princípios Centrais da Abertura de Recursos <a class="header-anchor" href="#iii-principios-centrais-da-abertura-de-recursos" aria-label="Permalink to &quot;III. Princípios Centrais da Abertura de Recursos&quot;">​</a></h2><h3 id="_3-1-principio-de-garantia-basica" tabindex="-1">3.1 Princípio de Garantia Básica <a class="header-anchor" href="#_3-1-principio-de-garantia-basica" aria-label="Permalink to &quot;3.1 Princípio de Garantia Básica&quot;">​</a></h3><p>Cada vida tem o direito de obter recursos de nível 1 e 2 necessários para manter o cultivo básico. Os recursos de garantia básica são fornecidos gratuitamente ou a baixo preço por meio do &quot;Sistema de Garantia de que Cada um Tem um Caminho&quot;, sem barreiras e sem discriminação. O padrão de garantia básica é ajustado periodicamente pelo Parlamento da República de Todas as Raças de acordo com a situação de recursos e o estágio de desenvolvimento da civilização, garantindo que o nível de garantia corresponda à capacidade de suporte da civilização.</p><h3 id="_3-2-principio-de-mais-trabalho-mais-ganho" tabindex="-1">3.2 Princípio de Mais Trabalho, Mais Ganho <a class="header-anchor" href="#_3-2-principio-de-mais-trabalho-mais-ganho" aria-label="Permalink to &quot;3.2 Princípio de Mais Trabalho, Mais Ganho&quot;">​</a></h3><p>Acima da garantia básica, a distribuição de recursos de nível 3 e acima toma como base principal o valor de contribuição do indivíduo para a rede simbiótica. Quanto maior a contribuição, mais recursos podem ser trocados e maior o nível. O princípio de mais trabalho, mais ganho incentiva os cultivadores a se esforçarem para elevar seu próprio reino e fazer maiores contribuições para a civilização, ao mesmo tempo que garante que os recursos fluam para os indivíduos e grupos mais capazes de utilizá-los eficientemente.</p><h3 id="_3-3-principio-antimonopolio" tabindex="-1">3.3 Princípio Antimonopólio <a class="header-anchor" href="#_3-3-principio-antimonopolio" aria-label="Permalink to &quot;3.3 Princípio Antimonopólio&quot;">​</a></h3><p>É estritamente proibido que qualquer indivíduo, organização ou raça monopolize recursos de cultivo. As medidas específicas antimonopólio incluem:</p><ul><li>Os recursos de nível 3 e acima mantidos por um único indivíduo ou organização não podem exceder 1% das reservas totais da civilização</li><li>É proibido acumular para especular — os detentores de recursos não podem acumular maliciosamente e inflar preços quando houver escassez de recursos</li><li>É proibida a posse exclusiva — recursos públicos (como veios espirituais públicos, reinos secretos públicos, etc.) não podem ser possuídos exclusivamente por particulares</li><li>Violações da lei antimonopólio serão severamente sancionadas pelo Tribunal de Âncora, incluindo confisco de recursos, zeramento do valor de contribuição, restrição de permissões de cultivo, etc.</li></ul><h3 id="_3-4-principio-de-uso-sustentavel" tabindex="-1">3.4 Princípio de Uso Sustentável <a class="header-anchor" href="#_3-4-principio-de-uso-sustentavel" aria-label="Permalink to &quot;3.4 Princípio de Uso Sustentável&quot;">​</a></h3><p>O desenvolvimento e uso de todos os recursos devem seguir o princípio da sustentabilidade, e não é permitida a exploração predatória do tipo &quot;secar o lago para pescar&quot;. Os requisitos específicos incluem:</p><ul><li>A velocidade de desenvolvimento de recursos não pode exceder a velocidade de regeneração natural dos recursos (para recursos não renováveis, é necessário formular planos alternativos)</li><li>O desenvolvimento de recursos deve passar por avaliação de impacto ambiental para evitar danos irreversíveis ao ecossistema</li><li>Para recursos ameaçados, implementar políticas de proibição ou restrição de exploração para proteger a capacidade de regeneração dos recursos</li><li>Incentivar o cultivo e síntese artificial de recursos raros por meio de meios técnicos (como engenharia de lei, tecnologia de duplicação, etc.) para reduzir a dependência de recursos naturais</li></ul><h3 id="_3-5-principio-de-abertura-e-transparencia" tabindex="-1">3.5 Princípio de Abertura e Transparência <a class="header-anchor" href="#_3-5-principio-de-abertura-e-transparencia" aria-label="Permalink to &quot;3.5 Princípio de Abertura e Transparência&quot;">​</a></h3><p>O processo de distribuição de recursos deve ser aberto e transparente, aceitando a supervisão de todas as vidas:</p><ul><li>As reservas, distribuição e situação de desenvolvimento de todos os recursos públicos são periodicamente divulgadas à sociedade</li><li>Os padrões, processos e resultados da distribuição de recursos são abertos e consultáveis</li><li>Estabelecer um mecanismo de apelação de distribuição de recursos, onde indivíduos que discordam do resultado da distribuição podem solicitar revisão</li><li>O &quot;Comitê de Equidade de Recursos&quot;, subordinado ao Tribunal de Âncora, supervisiona especificamente a equidade e legalidade da distribuição de recursos</li></ul><h2 id="iv-mecanismos-especificos-de-abertura-de-recursos" tabindex="-1">IV. Mecanismos Específicos de Abertura de Recursos <a class="header-anchor" href="#iv-mecanismos-especificos-de-abertura-de-recursos" aria-label="Permalink to &quot;IV. Mecanismos Específicos de Abertura de Recursos&quot;">​</a></h2><h3 id="_4-1-mecanismo-de-contrato-de-producao-conjunta" tabindex="-1">4.1 Mecanismo de Contrato de Produção Conjunta <a class="header-anchor" href="#_4-1-mecanismo-de-contrato-de-producao-conjunta" aria-label="Permalink to &quot;4.1 Mecanismo de Contrato de Produção Conjunta&quot;">​</a></h3><p>O contrato de produção conjunta é o projeto institucional central da abertura de recursos de cultivo, e seu modo de operação básico foi detalhado no documento &quot;Princípio de Distribuição de Mais Trabalho, Mais Ganho&quot;. No campo da abertura de recursos, as aplicações específicas do contrato de produção conjunta incluem:</p><ul><li><strong>Contrato de Veio Espiritual</strong>: Contratar veios espirituais públicos para grupos de cultivadores ou comunidades raciais, onde o contratante é responsável pela manutenção e desenvolvimento sustentável do veio e recebe uma proporção da produção do veio</li><li><strong>Contrato de Campo de Ervas</strong>: Contratar campos de ervas públicos para cultivadores com capacidade de plantio, onde o contratante é responsável pelo cultivo e cuidado das ervas espirituais, e a colheita é distribuída proporcionalmente</li><li><strong>Gestão de Reinos Secretos</strong>: Delegar reinos secretos de cultivo públicos a equipes profissionais para gestão, onde o gestor é responsável pela manutenção e segurança do reino, e os usuários pagam uma taxa de uso razoável</li><li><strong>Exploração de Recursos</strong>: Incentivar cultivadores a participar da exploração de recursos em áreas não desenvolvidas, onde os exploradores têm direito prioritário de contrato sobre os novos recursos descobertos</li></ul><h3 id="_4-2-mecanismo-de-troca-por-valor-de-contribuicao" tabindex="-1">4.2 Mecanismo de Troca por Valor de Contribuição <a class="header-anchor" href="#_4-2-mecanismo-de-troca-por-valor-de-contribuicao" aria-label="Permalink to &quot;4.2 Mecanismo de Troca por Valor de Contribuição&quot;">​</a></h3><p>A civilização simbiótica estabeleceu um &quot;Sistema de Troca por Valor de Contribuição&quot; unificado, onde os cultivadores podem acumular valor de contribuição fazendo contribuições para a rede simbiótica e depois trocar o valor de contribuição por vários recursos de cultivo:</p><ul><li>As formas de obtenção de valor de contribuição incluem: progresso no cultivo, compartilhamento de conhecimento, inovação tecnológica, serviço público, restauração ecológica, proteção civilizacional, etc.</li><li>O sistema de troca implementa &quot;preços claros&quot;, cada recurso tem um preço de valor de contribuição claro, e o preço é ajustado dinamicamente de acordo com a raridade e demanda do recurso</li><li>O sistema de troca suporta a função de &quot;adiantamento&quot; — cultivadores promissores podem adiantar uma certa quantidade de valor de contribuição para troca de recursos, e pagar no futuro fazendo contribuições</li><li>O sistema de troca está conectado em tempo real à rede de âncora, garantindo a segurança e confiabilidade do registro e troca do valor de contribuição</li></ul><h3 id="_4-3-mecanismo-de-abertura-gratuita-de-recursos-publicos" tabindex="-1">4.3 Mecanismo de Abertura Gratuita de Recursos Públicos <a class="header-anchor" href="#_4-3-mecanismo-de-abertura-gratuita-de-recursos-publicos" aria-label="Permalink to &quot;4.3 Mecanismo de Abertura Gratuita de Recursos Públicos&quot;">​</a></h3><p>Os seguintes tipos de recursos são abertos gratuitamente a todas as vidas:</p><ul><li><strong>Recursos de Conhecimento</strong>: Técnicas básicas dos trezentos sistemas de cultivo, experiências públicas de cultivo, materiais básicos de pesquisa de lei, etc.</li><li><strong>Recursos de Energia de Nível 1</strong>: Energia espiritual básica, cristais de energia comuns e outros recursos de energia de baixo nível amplamente distribuídos</li><li><strong>Espaços Públicos de Cultivo</strong>: Salas públicas de cultivo, salas básicas de percepção de lei, espaços isolados comuns, etc.</li><li><strong>Recursos Médicos Básicos</strong>: Técnicas básicas de cura, pílulas comuns de tratamento de ferimentos, serviços básicos de reabilitação, etc.</li><li><strong>Recursos Educacionais Básicos</strong>: Cursos básicos de cultivo, orientação de mentores iniciantes, uso de equipamentos gerais de cultivo, etc.</li></ul><h3 id="_4-4-mecanismo-de-distribuicao-direcionada-de-recursos-especiais" tabindex="-1">4.4 Mecanismo de Distribuição Direcionada de Recursos Especiais <a class="header-anchor" href="#_4-4-mecanismo-de-distribuicao-direcionada-de-recursos-especiais" aria-label="Permalink to &quot;4.4 Mecanismo de Distribuição Direcionada de Recursos Especiais&quot;">​</a></h3><p>Para recursos raros como os de nível 4 e 5, é implementado um mecanismo de &quot;distribuição direcionada&quot;:</p><ul><li>Recursos raros são priorizados para projetos-chave de nível civilizacional (como construção de âncoras, desenvolvimento de planos, superação tecnológica, etc.)</li><li>Para indivíduos com necessidades especiais (como necessidade de recursos específicos para romper um reino chave, necessidade de medicamentos raros para tratar ferimentos especiais, etc.), é possível obter distribuição direcionada por meio de solicitação e aprovação</li><li>O plano de distribuição de recursos raros é formulado pelo &quot;Comitê de Distribuição de Recursos&quot;, subordinado ao Parlamento da República de Todas as Raças, e executado após aprovação pelo parlamento</li><li>Os resultados da distribuição direcionada são divulgados à sociedade e aceitam supervisão</li></ul><h2 id="v-criacao-de-recursos-e-desenvolvimento-sustentavel" tabindex="-1">V. Criação de Recursos e Desenvolvimento Sustentável <a class="header-anchor" href="#v-criacao-de-recursos-e-desenvolvimento-sustentavel" aria-label="Permalink to &quot;V. Criação de Recursos e Desenvolvimento Sustentável&quot;">​</a></h2><p>A abertura de recursos de cultivo não é apenas &quot;distribuir o estoque existente&quot;, mas também &quot;criar incremento&quot;. A civilização simbiótica incentiva vigorosamente a criação artificial e o desenvolvimento sustentável de recursos:</p><h3 id="_5-1-cultivo-artificial-de-recursos" tabindex="-1">5.1 Cultivo Artificial de Recursos <a class="header-anchor" href="#_5-1-cultivo-artificial-de-recursos" aria-label="Permalink to &quot;5.1 Cultivo Artificial de Recursos&quot;">​</a></h3><ul><li><strong>Plantio Artificial de Ervas Espirituais</strong>: Por meio da tecnologia de engenharia de lei, cultivar várias ervas espirituais em ambientes artificiais para reduzir a dependência de ervas selvagens</li><li><strong>Produção Artificial de Energia</strong>: Por meio de tecnologias como dispositivos de conversão matéria-energia e geradores de ressonância de lei, produzir artificialmente energia espiritual e cristais de energia</li><li><strong>Criação Artificial de Bestas Espirituais</strong>: Estabelecer bases de criação de bestas espirituais, cultivar artificialmente várias bestas espirituais e proteger as populações selvagens</li><li><strong>Construção Artificial de Reinos Secretos</strong>: Por meio da tecnologia de lei espacial, construir artificialmente reinos secretos de cultivo para aumentar a oferta de espaços de cultivo</li></ul><h3 id="_5-2-reciclagem-de-recursos" tabindex="-1">5.2 Reciclagem de Recursos <a class="header-anchor" href="#_5-2-reciclagem-de-recursos" aria-label="Permalink to &quot;5.2 Reciclagem de Recursos&quot;">​</a></h3><ul><li><strong>Recuperação de Energia</strong>: Estabelecer sistemas de recuperação de energia para recuperar e reutilizar a energia perdida durante o cultivo, a energia dissipada em batalhas, etc.</li><li><strong>Processamento de Resíduos Medicinais</strong>: Realizar extração secundária e processamento de resíduos de ervas após a refinação de pílulas para melhorar a taxa de utilização dos recursos medicinais</li><li><strong>Recuperação e Reconstrução de Equipamentos</strong>: Recuperar e reconstruir equipamentos de cultivo descartados para reduzir o desperdício de materiais</li><li><strong>Uso Reciclável de Espaços</strong>: Limpar e reutilizar espaços isolados, espaços temporários de cultivo, etc., após o uso</li></ul><h3 id="_5-3-tecnologia-de-substituicao-de-recursos" tabindex="-1">5.3 Tecnologia de Substituição de Recursos <a class="header-anchor" href="#_5-3-tecnologia-de-substituicao-de-recursos" aria-label="Permalink to &quot;5.3 Tecnologia de Substituição de Recursos&quot;">​</a></h3><ul><li>Incentivar a pesquisa e desenvolvimento de substitutos para recursos raros, realizando &quot;substituir materiais raros por materiais comuns&quot; por meio de meios técnicos</li><li>Para recursos lendários não renováveis, formular planos rigorosos de proteção e uso, ao mesmo tempo que aumenta o investimento em pesquisa e desenvolvimento de tecnologias alternativas</li><li>Estabelecer um &quot;Fundo de Pesquisa e Desenvolvimento de Tecnologia de Substituição de Recursos&quot; para financiar projetos de pesquisa relacionados</li></ul><h2 id="vi-supervisao-e-remediacao-da-abertura-de-recursos" tabindex="-1">VI. Supervisão e Remediação da Abertura de Recursos <a class="header-anchor" href="#vi-supervisao-e-remediacao-da-abertura-de-recursos" aria-label="Permalink to &quot;VI. Supervisão e Remediação da Abertura de Recursos&quot;">​</a></h2><h3 id="_6-1-mecanismo-de-supervisao" tabindex="-1">6.1 Mecanismo de Supervisão <a class="header-anchor" href="#_6-1-mecanismo-de-supervisao" aria-label="Permalink to &quot;6.1 Mecanismo de Supervisão&quot;">​</a></h3><ul><li><strong>Monitoramento em Tempo Real pela Rede de Âncora</strong>: A rede de âncora monitora em tempo real o desenvolvimento, distribuição e uso de todos os recursos públicos, emitindo alertas oportunos ao detectar anomalias</li><li><strong>Comitê de Equidade de Recursos</strong>: Supervisiona especificamente a equidade e legalidade da distribuição de recursos, aceitando denúncias e reclamações</li><li><strong>Supervisão Social</strong>: Incentivar todas as vidas a supervisionar e denunciar comportamentos inadequados no desenvolvimento e distribuição de recursos</li><li><strong>Auditoria Periódica</strong>: Realizar auditorias independentes nos órgãos de gestão de recursos todos os anos, com os resultados da auditoria divulgados à sociedade</li></ul><h3 id="_6-2-mecanismo-de-remediacao" tabindex="-1">6.2 Mecanismo de Remediação <a class="header-anchor" href="#_6-2-mecanismo-de-remediacao" aria-label="Permalink to &quot;6.2 Mecanismo de Remediação&quot;">​</a></h3><ul><li><strong>Apelação de Distribuição</strong>: Indivíduos que discordam do resultado da distribuição de recursos podem solicitar revisão ao Comitê de Equidade de Recursos</li><li><strong>Arbitragem de Disputas de Recursos</strong>: Disputas de recursos são arbitradas pelo Tribunal de Âncora, e o resultado da arbitragem tem efeito legal</li><li><strong>Remediação por Violação</strong>: Indivíduos lesados por comportamentos como monopólio de recursos, saque de recursos, etc., podem entrar com ação no Tribunal de Âncora para reivindicar indenização</li><li><strong>Assistência de Emergência</strong>: Em situações especiais (como desastres, guerras, etc.), ativar o mecanismo de alocação emergencial de recursos para garantir as necessidades básicas de recursos dos grupos afetados</li></ul><h2 id="conclusao" tabindex="-1">Conclusão <a class="header-anchor" href="#conclusao" aria-label="Permalink to &quot;Conclusão&quot;">​</a></h2><p>O mecanismo de abertura de recursos de cultivo é o núcleo do sistema econômico da Civilização Simbiótica de Âncora. Por meio dos cinco princípios de &quot;garantia básica + mais trabalho, mais ganho + antimonopólio + sustentabilidade + abertura e transparência&quot;, ele constrói um sistema de distribuição de recursos equitativo, eficiente e sustentável. O objetivo final do mecanismo de abertura de recursos não é fazer com que todas as vidas obtenham a mesma quantidade de recursos, mas sim dar a cada vida uma oportunidade equitativa de acessar recursos, fazer com que os recursos fluam para os lugares mais capazes de criar valor e fazer com que a quantidade total de recursos da civilização cresça continuamente sob a premissa da sustentabilidade. Quando os recursos de cultivo não forem mais propriedade privada monopolizada por poucos, mas sim riqueza pública compartilhada por todas as raças e com ganho cíclico, o ideal de &quot;cada um tem um caminho&quot; poderá verdadeiramente se concretizar, e o objetivo de progresso comum de todas as raças poderá verdadeiramente ser alcançado.</p><h2 id="documentos-relacionados" tabindex="-1">Documentos Relacionados <a class="header-anchor" href="#documentos-relacionados" aria-label="Permalink to &quot;Documentos Relacionados&quot;">​</a></h2><ul><li>06-多劳多得分配原理 (Princípio de Distribuição de Mais Trabalho, Mais Ganho)</li><li>08-人人有路保障体系 (Sistema de Garantia de que Cada um Tem um Caminho)</li><li>22-资源分配联产承包机制 (Mecanismo de Contrato de Produção Conjunta de Distribuição de Recursos)</li></ul>',57)])])}const v=o(r,[["render",t]]);export{p as __pageData,v as default};
